        return (float('inf'), None)

    def has_cycle(graph):
        visited = set()
        stack = []

        def dfs(node):
            visited.add(node)
            stack.append(node)
            for neighbor, _ in graph.get(node, []):
                if neighbor not in visited:
                    dfs(neighbor)
                elif neighbor in stack:
                    return True
            stack.pop()
            return False
        return any((dfs(node) for node in graph if node not in visited))

    def find_shortest_path_dfs(graph, source, target):
        if source == target:
            return (0, [source])
        visited = set()
        stack = deque([(source, [source])])
        while stack:
            current, path = stack.popleft()
            if current == target:
                return (0, path)
            visited.add(current)
            for neighbor, weight in graph.get(current, []):
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))
        return (float('inf'), None)
    if has_cycle(graph):
        return (float('inf'), None)
    return find_shortest_path_dfs(graph, source, target)
